import unix_compress

VERSION = """Ancient v2.3.0
Copyright (C) Teemu Suutari

Usage: ancient i[dentify] packed_input_files...
 - identifies compression used in a file(s)
Usage: ancient v[erify] packed_input_file unpacked_comparison_file
 - verifies decompression against known good unpacked file
Usage: ancient [-p] d[ecompress] packed_input_file output_file
 - decompresses single file
 - use p-flag to preserve timestamp of the original"""


def fail(s):
    print(s, file=sys.stderr)
    return 255


class DecompressionFailed(Exception):
    pass


def decode(data):
    if data.startswith(b"\x1f\x8b"):
        remaining = data
        first = None
        while remaining:
            dec = zlib.decompressobj(31)
            part = dec.decompress(remaining) + dec.flush()
            if not dec.eof:
                raise ValueError
            if first is None:
                first = part
            remaining = dec.unused_data
        if first is None or not first:
            raise ValueError
        return "gzip: Deflate", first
    if data.startswith(b"BZh"):
        try:
            dec = bz2.BZ2Decompressor()
            result = dec.decompress(data)
            if not dec.eof:
                raise DecompressionFailed
            return "bz2: bzip2", result
        except DecompressionFailed:
            raise
        except Exception as e:
            raise DecompressionFailed from e
    if data.startswith(b"\x1f\x9d"):
        label = "Z: Compress (new)" if len(data) > 2 and data[2] & 0x80 else "Z: Compress (old)"
        return label, unix_compress.decompress(data)
    raise ValueError


def main(argv):
    preserve = False
    if argv and argv[0] == "-p":
        preserve = True
        argv = argv[1:]
    if not argv:
        print(VERSION, file=sys.stderr)
        return 255
    cmd = argv[0]
    if cmd in ("identify", "i"):
        if len(argv) < 2:
            print(VERSION, file=sys.stderr)
            return 255
        rc = 0
        for path in argv[1:]:
            try:
                data = open(path, "rb").read()
            except OSError:
                rc = fail("Could not read file " + path)
                continue
            try:
                if data.startswith(b"\x1f\x1e") and len(data) >= 6:
                    name = "z: Pack"
                elif data.startswith(b"\x1f\x9e"):
                    name = "F: Freeze/Melt 1.x"
                elif (data.startswith(b"\x1f\x9d") and len(data) >= 4
                      and not (data[2] & 0x60)
                      and 9 <= (data[2] & 0x1f) <= 16):
                    decode(data)
                    name = "Z: Compress (new)" if len(data) > 2 and data[2] & 0x80 else "Z: Compress (old)"
                elif data.startswith(b"\x1f\xa0") and len(data) >= 4:
                    name = "SCO Compress LZH"
                elif data.startswith(b"BZh") and len(data) >= 4 and data[3:4] in b"123456789":
                    name = "bz2: bzip2"
                else:
                    name, _ = decode(data)
                print(f"Compression of {path} is {name}")
