    if cmd in ("verify", "v"):
        if len(argv) != 3:
            print(VERSION, file=sys.stderr)
            return 255
        packed, expected = argv[1:]
        try:
            src = open(packed, "rb").read()
        except OSError:
            return fail("Could not read file " + packed)
        try:
            reference = open(expected, "rb").read()
        except OSError:
            return fail("Could not read file " + expected)
        try:
            _, result = decode(src)
        except DecompressionFailed:
            return fail(f"Decompression failed for {packed}")
        except Exception:
            return fail(f"Unknown or invalid compression format in file {packed}")
        if len(result) != len(reference):
            return fail(f"Verify failed for {packed} and {expected} - sizes differ")
