            st = os.stat(packed)
            src = open(packed, "rb").read()
        except OSError:
            return fail("Could not read file " + packed)
        try:
            _, result = decode(src)
        except DecompressionFailed:
            return fail(f"Decompression failed for {packed}")
        except Exception:
            return fail(f"Unknown or invalid compression format in file {packed}")
        try:
            with open(output, "wb") as f:
                f.write(result)
            if preserve:
                os.utime(output, (st.st_atime, st.st_mtime))
        except OSError:
            print("Could not write file " + output, file=sys.stderr)
        return 0
    print(VERSION, file=sys.stderr)
    return 255


